def encode(request, data):
        if data is None:
            return request

        request.add_header('Content-Type', 'application/json')
        request.data = json.dumps(data)

        return request

def get(self, url, params=None, **kwargs):
        return self.call_api(
            "GET",
            url,
            params=params,
            **kwargs
        )

def delete(self, url, params=None, **kwargs):
        return self.call_api(
            "DELETE",
            url,
            params=params,
            **kwargs
